"""
    Returns period of 1/n

    Parameters
    ----------
    n : int
        denotes positive integer
    return : int
        returns an integer denoting period of 1/n

    """
def getPeriod(n: Any) -> object {
    if ((n != int(n)) or (n < 1)) {
        raise ValueError("n must be positive integer");
    }
    rem = 1;
    for i in range(1, (n + 2)) {
        rem = (10 * rem) % n;
    }
    d = rem;
    count = 0;
    rem = (10 * rem) % n;
    count += 1;
    while (rem != d) {
        rem = (10 * rem) % n;
        count += 1;
    }
    return count;
}

""" Return a subdirectory used when a big case is split into several pieces """
def splitdir(idx: Any) -> object {
    name = '';
    if (len(idx) == 0) {
        return '';
    }
    for (ii, n) in enumerate(idx[0:]) {
        name += 'sp%d-split-%d/' % (ii, n);
    }
    name = name[0:-1];
    return name;
}

